+// Temporary native wake analysis probe; removed after evidence capture.
+const WakeAnalysis = struct {
+    var active: ?*Spy = null;
+    const Spy = struct {
+        calls: std.atomic.Value(usize) = .init(0),
+        delivered: std.atomic.Value(usize) = .init(0),
+        mode: u8 = 0,
+        fail_first: usize = 0,
+        fn wake(_: ?*anyopaque) anyerror!void {
+            const self = active.?;
+            const call = self.calls.fetchAdd(1, .acq_rel) + 1;
+            if (self.mode == 1 or call <= self.fail_first) return error.InjectedWakeFailure;
+            if (self.mode == 0) _ = self.delivered.fetchAdd(1, .release);
+        }
+    };
+    const Activation = @import("app/single_instance.zig");
+    const Notice = struct {
+        adapter: *app_platform.Adapter,
+        unavailable: std.atomic.Value(usize) = .init(0),
+        scheduled: std.atomic.Value(usize) = .init(0),
+        fn notify(context: ?*anyopaque) bool {
+            const self: *@This() = @ptrCast(@alignCast(context.?));
+            const result = app_platform.Adapter.notifyMainLoop(self.adapter);
+            if (result) { _ = self.scheduled.fetchAdd(1, .release); }
+            else { _ = self.unavailable.fetchAdd(1, .release); }
+            return result;
+        }
+    };
+    const Submit = struct {
+        queue: *Activation.ActivationQueue,
+        frame: []const u8,
+        status: Activation.Status = .rejected,
+        fn run(self: *@This()) void { self.status = self.queue.accept(self.frame); }
+    };
+    fn submit(queue: *Activation.ActivationQueue, frame: []const u8) !Activation.Status {
+        var job: Submit = .{ .queue = queue, .frame = frame };
+        const thread = try std.Thread.spawn(.{}, Submit.run, .{&job});
+        thread.join();
+        return job.status;
+    }
+    fn setup(spy: *Spy) !*native_sdk.TestHarness() {
+        active = spy;
+        const harness = try native_sdk.TestHarness().create(std.testing.allocator, .{});
+        harness.runtime.options.platform.services.wake_fn = Spy.wake;
+        return harness;
+    }
+};
+
+test "wake probe startup queued activation survives unavailable wake" {
+    var spy: WakeAnalysis.Spy = .{};
+    const harness = try WakeAnalysis.setup(&spy);
+    defer harness.destroy(std.testing.allocator);
+    var adapter = app_platform.Adapter.init(std.testing.io, std.Thread.getCurrentId());
+    var notice: WakeAnalysis.Notice = .{ .adapter = &adapter };
+    const identity = WakeAnalysis.Activation.Identity.init("probe", "/probe-data-root");
+    var queue = WakeAnalysis.Activation.ActivationQueue.init(std.testing.io, identity, .{ .context = &notice, .notify_fn = WakeAnalysis.Notice.notify });
+    var storage: [WakeAnalysis.Activation.max_frame_bytes]u8 = undefined;
+    const frame = try WakeAnalysis.Activation.encodeRequest(&storage, identity, "/", &.{"metawork"});
+    try std.testing.expectEqual(.accepted, try WakeAnalysis.submit(&queue, frame));
+    try std.testing.expectEqual(@as(usize, 1), notice.unavailable.load(.acquire));
+    try adapter.start(&harness.runtime);
+    defer adapter.stop(&harness.runtime);
+    try std.testing.expect(queue.drain());
+    try std.testing.expect(!queue.drain());
+    std.debug.print("WAKE_PROBE startup accepted=1 unavailable=1 startup_drain=1 lost_activation=0\n", .{});
+}
+
+test "wake probe running failed activation notification is acknowledged without retry" {
+    var spy: WakeAnalysis.Spy = .{ .mode = 1 };
+    const harness = try WakeAnalysis.setup(&spy);
+    defer harness.destroy(std.testing.allocator);
+    var adapter = app_platform.Adapter.init(std.testing.io, std.Thread.getCurrentId());
+    try adapter.start(&harness.runtime);
