+    try std.testing.expectEqual(.accepted, try WakeAnalysis.submit(&queue, frame));
+    try std.Io.sleep(std.testing.io, .fromMilliseconds(10), .awake);
+    try std.testing.expectEqual(@as(usize, 1), spy.calls.load(.acquire));
+    try std.testing.expectEqual(@as(usize, 0), spy.delivered.load(.acquire));
+    try std.testing.expectEqual(@as(usize, 1), notice.unavailable.load(.acquire));
+    try std.testing.expect(queue.pending);
+    std.debug.print("WAKE_PROBE running_failure accepted=1 sdk_calls=1 unavailable=1 delivered=0 pending=1 retries=0\n", .{});
