+    std.debug.print("WAKE_PROBE injected_dependency_silent_drop sdk_calls=1 scheduled=1 coalesced=1 delivered=0\n", .{});
+}
+
+test "wake probe startup binding concurrent access stress" {
+    var spy: WakeAnalysis.Spy = .{};
+    const harness = try WakeAnalysis.setup(&spy);
+    defer harness.destroy(std.testing.allocator);
+    var adapter = app_platform.Adapter.init(std.testing.io, std.Thread.getCurrentId());
+    var notice: WakeAnalysis.Notice = .{ .adapter = &adapter };
+    const Worker = struct {
+        notice: *WakeAnalysis.Notice,
+        entered: std.atomic.Value(bool) = .init(false),
+        fn run(self: *@This()) void {
+            _ = WakeAnalysis.Notice.notify(self.notice);
+            self.entered.store(true, .release);
+            for (0..100_000) |_| _ = WakeAnalysis.Notice.notify(self.notice);
+        }
+    };
+    var worker: Worker = .{ .notice = &notice };
+    const thread = try std.Thread.spawn(.{}, Worker.run, .{&worker});
+    while (!worker.entered.load(.acquire)) std.Thread.yield() catch {};
+    try adapter.start(&harness.runtime);
+    thread.join();
+    defer adapter.stop(&harness.runtime);
+    try std.testing.expectEqual(@as(usize, 100_001), notice.unavailable.load(.acquire) + notice.scheduled.load(.acquire));
+    std.debug.print("WAKE_PROBE startup_stress calls=100001 unavailable={d} scheduled={d} sanitizer_required_for_race_verdict=1\n", .{ notice.unavailable.load(.acquire), notice.scheduled.load(.acquire) });
+}
+
+test "wake probe required notification failure child" {
