+}
+
+// C ABI entry only for ThreadSanitizer analysis of the actual Adapter methods.
+pub export fn metaworkWakeProbeRace() c_int {
+    var spy: WakeAnalysis.Spy = .{};
+    WakeAnalysis.active = &spy;
+    const harness = native_sdk.TestHarness().create(std.heap.c_allocator, .{}) catch return 1;
+    defer harness.destroy(std.heap.c_allocator);
+    harness.runtime.options.platform.services.wake_fn = WakeAnalysis.Spy.wake;
+    var adapter = app_platform.Adapter.init(std.Io.Threaded.global_single_threaded.io(), std.Thread.getCurrentId());
+    std.debug.print("WAKE_PROBE tsan_target platform_services_begin=0x{x} bytes={d} source=src/app/platform.zig:44,135\n", .{ @intFromPtr(&adapter.platform_services), @sizeOf(@TypeOf(adapter.platform_services)) });
+    const Worker = struct {
+        adapter: *app_platform.Adapter,
+        entered: std.atomic.Value(bool) = .init(false),
+        hits: std.atomic.Value(usize) = .init(0),
+        fn run(self: *@This()) void {
+            _ = app_platform.Adapter.notifyMainLoop(self.adapter);
+            self.entered.store(true, .release);
+            for (0..100_000) |_| {
+                if (app_platform.Adapter.notifyMainLoop(self.adapter)) _ = self.hits.fetchAdd(1, .monotonic);
+            }
+        }
+    };
+    var worker: Worker = .{ .adapter = &adapter };
+    const thread = std.Thread.spawn(.{}, Worker.run, .{&worker}) catch return 2;
+    while (!worker.entered.load(.acquire)) std.Thread.yield() catch {};
+    adapter.start(&harness.runtime) catch return 3;
+    thread.join();
+    adapter.stop(&harness.runtime);
+    std.debug.print("WAKE_PROBE tsan_actual_adapter completed scheduled={d}\n", .{worker.hits.load(.acquire)});
+    return 0;
+}
