+    var request_storage: [WakeAnalysis.Activation.max_frame_bytes]u8 = undefined;
+    const request = try WakeAnalysis.Activation.encodeRequest(&request_storage, identity, root, &.{"metawork-wake-probe"});
+    const transport = @import("metawork_app_single_instance_compat");
