+    var count = try transport.forward(std.testing.allocator, root, request, &response);
+    try std.testing.expectEqual(.accepted, try WakeAnalysis.Activation.decodeResponse(response[0..count]));
+    try std.testing.expectEqual(@as(usize, 1), notice.unavailable.load(.acquire));
+    try adapter.start(&harness.runtime);
+    try std.testing.expect(coordinator.drain());
+    count = try transport.forward(std.testing.allocator, root, request, &response);
+    try std.testing.expectEqual(.accepted, try WakeAnalysis.Activation.decodeResponse(response[0..count]));
+    try std.testing.expectEqual(@as(usize, 2), notice.unavailable.load(.acquire));
+    try std.testing.expectEqual(@as(usize, 1), spy.calls.load(.acquire));
+    try std.testing.expectEqual(@as(usize, 0), spy.delivered.load(.acquire));
+    coordinator.queue.mutex.lockUncancelable(std.testing.io);
