+        fn run(self: *@This()) void {
+            _ = self.queue.accept(self.frame);
+            self.entered.store(true, .release);
+            for (0..100_000) |_| _ = self.queue.accept(self.frame);
+        }
+    };
+    var worker: Worker = .{ .queue = &queue, .frame = frame };
+    var started = false;
+    defer {
+        queue.stop();
+        if (started) adapter.stop(&harness.runtime);
+    }
+    {
+        const thread = std.Thread.spawn(.{}, Worker.run, .{&worker}) catch return 3;
+        defer thread.join();
+        while (!worker.entered.load(.acquire)) std.Thread.yield() catch {};
