+        started = true;
+        if (!queue.bindWakeAndDrain(.{ .context = &adapter, .notify_fn = app_platform.Adapter.notifyMainLoop })) return 5;
+    }
+    if (queue.accept(frame) != .accepted or !queue.drain()) return 6;
+    std.debug.print("WAKE_FIXED_TSAN actual Adapter + ActivationQueue startup publication complete\n", .{});
+    return 0;
+}
+
+pub fn wakeSmoke(init: std.process.Init) !void {
+    const Smoke = struct {
+        adapter: app_platform.Adapter,
+        worker: ?std.Thread = null,
+        scheduled: bool = false,
+        delivered: bool = false,
+        main_thread: std.Thread.Id,
+        fn start(context: *anyopaque, runtime: *native_sdk.Runtime) !void {
+            const self: *@This() = @ptrCast(@alignCast(context));
+            try self.adapter.start(runtime);
+            self.worker = try std.Thread.spawn(.{}, wake, .{self});
+        }
+        fn wake(self: *@This()) void {
+            self.scheduled = app_platform.Adapter.notifyMainLoop(&self.adapter);
+        }
+        fn event(context: *anyopaque, runtime: *native_sdk.Runtime, value: native_sdk.Event) !void {
+            const self: *@This() = @ptrCast(@alignCast(context));
+            if (value == .effects_wake) {
+                if (std.Thread.getCurrentId() != self.main_thread) return error.WrongWakeThread;
+                self.delivered = true;
+                std.debug.print("WAKE_FIXED_MACOS effects_wake on main thread\n", .{});
+                try runtime.closeWindow(1);
+            }
+        }
+        fn stop(context: *anyopaque, runtime: *native_sdk.Runtime) !void {
+            const self: *@This() = @ptrCast(@alignCast(context));
+            if (self.worker) |thread| thread.join();
+            self.adapter.stop(runtime);
+        }
+    };
+    var smoke: Smoke = .{ .adapter = app_platform.Adapter.init(init.io, std.Thread.getCurrentId()), .main_thread = std.Thread.getCurrentId() };
+    defer smoke.adapter.deinit();
+    try runner.runWithOptions(.{
+        .context = &smoke,
+        .name = "metawork-wake-verification",
+        .source = native_sdk.WebViewSource.html("<!doctype html><title>Wake verification</title>"),
+        .start_fn = Smoke.start,
+        .event_fn = Smoke.event,
+        .stop_fn = Smoke.stop,
+    }, .{
+        .app_name = "MetaWork wake verification",
+        .window_title = "MetaWork wake verification",
+        .bundle_id = "com.metask.metawork.wake-verification",
+        .restore_state = false,
+    }, init);
+    if (!smoke.scheduled or !smoke.delivered) return error.WakeNotDelivered;
+    std.debug.print("WAKE_FIXED_MACOS scheduled=1 delivered=1 clean_shutdown=1\n", .{});
+}
+
+const WakeControlVerification = struct {
+    var calls: usize = 0;
+    var fail_always = false;
+    fn wake(_: ?*anyopaque) anyerror!void {
+        calls += 1;
+        if (fail_always or calls <= 2) return error.InjectedWakeFailure;
+    }
+};
+pub export fn metaworkWakeControls(required: bool) c_int {
+    const T = WakeControlVerification;
+    T.calls = 0;
+    T.fail_always = required;
+    var io_state = std.Io.Threaded.init(std.heap.c_allocator, .{});
+    defer io_state.deinit();
+    const harness = native_sdk.TestHarness().create(std.heap.c_allocator, .{}) catch return 1;
+    defer harness.destroy(std.heap.c_allocator);
+    harness.runtime.options.platform.services.wake_fn = T.wake;
+    var adapter = app_platform.Adapter.init(io_state.io(), std.Thread.getCurrentId());
+    adapter.start(&harness.runtime) catch return 2;
+    defer adapter.stop(&harness.runtime);
+    if (required) app_platform.Adapter.notifyRequired(&adapter);
+    var coordinator: agent_event_coordinator.Coordinator = .{};
+    coordinator.bindWake(.{ .context = &adapter, .notify_fn = app_platform.Adapter.notifyMainLoop });
+    const result = coordinator.notifier().notifyWithRetry(io_state.io(), .fromMilliseconds(1), .fromMilliseconds(20));
+    if (result != .scheduled or T.calls != 3 or coordinator.notifier().notify() != .already_pending) return 3;
+    std.debug.print("WAKE_FIXED_CONTROLS Agent failures=2 scheduled_on_call=3 coalesced=1\n", .{});
+    return 0;
+}
